  "difficulty": "TOEFL iBT",
  "wordCount": 148,
  "text": "As climate change impacts become increasingly visible, governments face a difficult choice: should they prioritize mitigating climate change by reducing emissions, or adapting to its effects? Governments should place greater emphasis on adaptation for three reasons.\n\nFirst, some impacts are already unavoidable. Rising sea levels and intensified storms will continue for decades due to climate inertia, even if emissions are drastically reduced today. Adaptation measures such as flood defenses and disaster preparedness are therefore necessary.\n\nSecond, adaptation protects vulnerable populations. Low-income communities and elderly people are disproportionately affected by climate hazards. Early warning systems and resilient housing can significantly reduce harm.\n\nThird, adaptation delivers immediate, tangible benefits. Urban green spaces can reduce heat stress and improve air quality right away.\n\nCritics argue this may weaken mitigation efforts. However, a balanced approach strengthening both adaptation and mitigation is essential.",
