  "translation": "気候変動の影響がますます明確になるにつれ、各国政府は難しい選択に直面している。排出削減による気候変動の緩和を優先すべきか、その影響への適応を優先すべきか。政府は3つの理由から適応により重点を置くべきである。\n\n第一に、一部の影響はすでに避けられない。海面上昇や暴風雨の激化は、たとえ今日排出量が大幅に削減されても、気候の慣性により今後数十年続く。洪水防御や災害対策などの適応策は不可欠である。\n\n第二に、適応は脆弱な人々を守る。低所得層や高齢者は気候災害の影響を不均衡に受けている。早期警報システムや耐性のある住宅は被害を大きく減らせる。\n\n第三に、適応は即時的で具体的な利益をもたらす。都市の緑地は熱ストレスを軽減し、大気の質をすぐに改善できる。\n\n批判者はこれが緩和努力を弱めると主張する。しかし、適応と緩和の両方を強化するバランスの取れたアプローチが不可欠である。"
