  "text": "Central banks have long relied on interest rate adjustments to manage inflation. However, in an interconnected global economy, domestic monetary policy faces structural constraints that limit its effectiveness.\n\nSupply chain disruptions pose an intractable challenge. The COVID-19 pandemic showed how bottlenecks in distant manufacturing hubs could trigger worldwide price increases. When inflation stems from supply-side shocks, raising rates may suppress economic activity without reducing prices.\n\nCurrency dynamics further complicate matters. Interest rate decisions in one country can precipitate capital flight from another, destabilizing exchange rates. Emerging economies are especially susceptible to these spillover effects.\n\nThe financialization of commodity markets adds complexity. Oil and wheat prices are increasingly driven by speculative trading rather than supply and demand fundamentals. Central banks have virtually no tools to counteract this volatility.\n\nDespite these limitations, central banks remain indispensable. Their credibility anchors public expectations. Yet addressing inflation increasingly requires coordinated international action rather than unilateral monetary intervention.",
