  "translation": "司会者：「マインド・マターズ」にお帰りなさい。今日はソーシャルメディアとメンタルヘルスの複雑な関係を議論します。オカフォー博士、現在の合意はどうですか？\n\nオカフォー博士：ニュアンスが重要です。実証的なエビデンスは複雑な全体像を描いています。プラットフォーム自体が本質的に有害なのではなく、それらが育む行動パターンこそが精査に値します。\n\n司会者：詳しく説明していただけますか？\n\nオカフォー博士：受動的な消費と能動的な関与を考えてみてください。人々が参加せずに厳選されたハイライト集をスクロールするだけの場合、「上方社会比較」を経験します。自分のフィルターのない現実を他者の作り上げたペルソナと絶えず比較するのです。その影響として、不安の増大や自己肯定感の低下があります。\n\n司会者：有益な側面はありますか？\n\nオカフォー博士：間違いなく。ソーシャルメディアはメンタルヘルスリソースへのアクセスを民主化しました。疎外されたコミュニティがオンラインで連帯を見出し、青少年が地理的境界を越えて支援的な仲間とつながっています。\n\n司会者：どこから有害になるのですか？\n\nオカフォー博士：刺激的なコンテンツのアルゴリズムによる増幅が陰湿です。ドーパミン駆動のフィードバックループが社会的承認への素因を利用します。ユーザーは具体的な悪影響が出るまで強迫的な使用に気づかないことが多いのです。\n\n司会者：お勧めは？\n\nオカフォー博士：デジタル環境の意図的なキュレーションが最重要です。時間的境界を設け、プラットフォームが自分にどう感じさせるかを点検してください。"
