  "text": "The envelope had been sitting on Elena's desk for three days, its presence as oppressive as the August humidity. She knew what it contained—irrefutable evidence of her colleague Martin's embezzlement, meticulously documented across dozens of falsified invoices.\n\nMartin had been her mentor, the person who had advocated tirelessly for her promotion. His generosity was genuine, but so was his transgression.\n\nThe quandary consumed her. Reporting him would reverberate beyond Martin himself, devastating his family. Yet silence would make her complicit in fraud that deprived community programs of desperately needed resources.\n\nShe retrieved a photograph—Martin at a charity gala, surrounded by the very beneficiaries whose funds he had siphoned. The juxtaposition was unbearable. But people were not monolithic entities. They were constellations of competing motivations, capable of kindness and selfishness within the same breath.\n\nElena sealed the envelope. The decision felt neither righteous nor treacherous—simply the irreducible minimum that integrity demanded.",
