  "difficulty": "TOEFL iBT",
  "wordCount": 155,
  "text": "Sarah: I've been toying with the idea of visiting Patagonia next February. Have you ever been?\n\nMarcus: I trekked through Torres del Paine a couple of years ago—absolutely breathtaking. But the logistics can be surprisingly tricky.\n\nSarah: What do you mean? I assumed you could just fly into Santiago and head south.\n\nMarcus: The domestic flights get booked up months ahead during peak season. Accommodation near the park is limited and exorbitantly priced. Even designated campsites sell out within hours.\n\nSarah: That sounds daunting. Is it worth the hassle?\n\nMarcus: Without a doubt. Massive glaciers calving into turquoise lakes, condors soaring above jagged granite spires, guanacos grazing on windswept plains. The sheer scale makes you feel wonderfully insignificant.\n\nSarah: What about the weather?\n\nMarcus: We experienced all four seasons in one afternoon—sunshine, horizontal rain, hail, then eerie calm. Layering is essential, and invest in a windproof jacket. Patagonian winds are ferocious.\n\nSarah: Any cultural recommendations?\n\nMarcus: Spend a few days in Valparaíso. The street art is phenomenal, the seafood spectacular, and the hillside funiculars offer panoramic Pacific views—a perfect counterpoint to the southern wilderness.\n\nSarah: Consider me convinced. Let's plan an itinerary this weekend.",
