  "translation": "サラ：来年2月にパタゴニアを訪れるアイデアを考え始めているの。行ったことある？\n\nマーカス：数年前にトーレス・デル・パイネをトレッキングしたんだ—本当に息をのむほどだった。でも段取りが意外とやっかいでね。\n\nサラ：どういう意味？サンティアゴに飛んで南下すればいいだけだと思っていたけど。\n\nマーカス：ピークシーズンの国内線は何か月も前に予約でいっぱいになる。公園近くの宿泊施設は限られていて法外に高い。指定キャンプ場でさえ数時間で売り切れる。\n\nサラ：気後れするわね。面倒に見合う価値はある？\n\nマーカス：間違いなくある。巨大な氷河がターコイズブルーの湖に崩落し、コンドルがギザギザの花崗岩の尖塔の上を舞い、グアナコが吹きさらしの平原で草を食む。そのスケールの大きさに自分がちっぽけに感じられて素晴らしいんだ。\n\nサラ：天気はどう？\n\nマーカス：一度の午後で四季すべてを経験した—日差し、横殴りの雨、雹、そして不気味な静けさ。レイヤリングは不可欠で、防風ジャケットに投資すべきだ。パタゴニアの風は猛烈だから。\n\nサラ：文化的なおすすめは？\n\nマーカス：バルパライソに数日過ごすべき。ストリートアートは驚異的、シーフードは素晴らしく、丘のケーブルカーから太平洋のパノラマの景色が楽しめる—南の荒野への完璧な対比だよ。\n\nサラ：説得されたわ。今週末に旅程を計画しましょう。"
