  "translation": "2015年から2025年の間に失敗した2千社以上のベンチャー支援スタートアップの徹底的な分析は、シリコンバレーの支配的な神話に挑戦するパターンを明らかにしている。一般的な物語に反して、スタートアップ失敗の最も一般的な原因は間違った製品を作ることではなく、初期のトラクションから持続可能な成長への軌道を管理し損なうことだ。\n\n失敗したスタートアップの約42%が、時期尚早な拡大を消滅の主要因として挙げた。初期の資金調達の成功に勢いづけられ、これらの企業は信頼できるユニットエコノミクスを確立する前に人員とマーケティングを積極的に拡大し、キャッシュバーンが収益創出を上回った。\n\n共同創業者間の対立が29%で2番目に多い失敗モードであった。異なるビジョンと不公平な株式配分が組織の麻痺を生んだ。注目すべきことに、正式な共同創業者契約を持つスタートアップはこの失敗を半分未満の割合で経験した。\n\n市場のタイミングが18%を占めた—いくつかの有望な企業が、必要なインフラや規制の枠組みが成熟する前に技術的には優れた製品を発売した。\n\n興味深いことに、2度目の創業者は有意に成功率が高くなく、生存者バイアスが経験の利点を膨張させ、シリアルファウンダーへの選好は経験的に根拠のないヒューリスティックである可能性が示唆された。"
