  "translation": "過去10年間のプロサッカーの変革は、アスリートと同様に統計学者に負うところが大きい。かつて直感とベテラン監督のカリスマ的権威に支配されていたスポーツは、期待ゴールモデルやプレス指標がすべての戦術的決定に情報を提供する領域へと進化した。\n\nその触媒は、分析手法を早期に取り入れたクラブの成功であった。マイケル・エドワーズ率いるリバプールの採用は、プレッシャー下での空間認識やオフ・ザ・ボールの動きの効率性という従来のスカウティングでは見えない属性を測定する独自のアルゴリズムで過小評価された選手を特定した。\n\n追跡データの普及により、コーチは相手の戦略を精密に分析できるようになった。試合前の準備には、各対戦相手に特有の守備の脆弱性をアルゴリズムで生成した可視化で研究する没入型ビデオセッションが含まれる。\n\nしかし、批判者は収束的なデータインサイトに駆動された戦術アプローチの均質化が、かつて大会を魅力的にしていたスタイルの多様性を減少させたと主張する。\n\nさらに、定量的指標はリーダーシップ、冷静さ、チームメイトを鼓舞する能力といったアルゴリズムによる定量化に抵抗する無形の資質を過小評価するリスクがある。最も洞察力のある監督は、データが経験に基づく判断を取って代わるのではなく補完すべきだと認識している。"
