  "difficulty": "TOEFL iBT+",
  "wordCount": 152,
  "text": "Research has revealed a bidirectional communication system between the gastrointestinal tract and the central nervous system—the gut-brain axis. This discovery is reshaping our understanding of psychiatric disorders and opening unprecedented therapeutic avenues.\n\nThe human gut harbors approximately thirty-eight trillion microorganisms—the microbiome—that produce neurotransmitters, short-chain fatty acids, and inflammatory mediators influencing brain function. Remarkably, the gut manufactures about 95% of the body's serotonin. Disruptions to microbial populations responsible for serotonin synthesis have been correlated with elevated rates of depression and anxiety.\n\nClinical trials of targeted probiotic interventions have yielded promising results. Randomized controlled studies showed that Lactobacillus and Bifidobacterium strains significantly reduced anxiety and lowered cortisol levels, spawning a new category called \"psychobiotics.\"\n\nThe vagus nerve serves as a primary conduit, transmitting signals from intestinal microbes to brain regions governing emotions. Microbial metabolites can also cross the blood-brain barrier and directly modulate neural activity.\n\nHowever, researchers caution against premature enthusiasm. The replication crisis has afflicted microbiome studies, and establishing causal relationships requires larger longitudinal investigations.",
