  "translation": "研究は消化管と中枢神経系の間の双方向コミュニケーションシステム——腸脳軸——を明らかにしてきた。この発見は精神疾患の理解を再形成し、前例のない治療的道を開いている。\n\n人間の腸は約38兆の微生物——マイクロバイオーム——を宿しており、それらは脳機能に影響を与える神経伝達物質、短鎖脂肪酸、炎症メディエーターを産生する。驚くべきことに、腸は体内のセロトニンの約95%を製造する。セロトニン合成を担う微生物集団の乱れは、うつ病と不安の発生率上昇と相関している。\n\n標的化されたプロバイオティクス介入の臨床試験は有望な結果をもたらした。無作為化対照試験は、ラクトバチルスとビフィドバクテリウム株が不安を有意に減少させコルチゾールレベルを低下させたことを示し、「サイコバイオティクス」という新しいカテゴリーを生み出した。\n\n迷走神経は主要な伝達経路として機能し、腸内微生物からの信号を感情を管轄する脳領域に伝達する。微生物の代謝産物は血液脳関門を通過し、神経活動を直接調節することもできる。\n\nしかし、研究者は早まった熱狂に警告する。再現性の危機はマイクロバイオーム研究にも影響しており、因果関係の確立にはより大規模な縦断的調査が必要である。"
