  "wordCount": 153,
  "text": "Detective Superintendent Claire Hargrove surveyed the disheveled study with the meticulous attention that twenty-three years of investigative work had instilled in her. The mahogany desk was undisturbed, a half-finished glass of Bordeaux standing where its owner had abandoned it. No forced entry. No struggle. Lord Ashworth had simply vanished.\n\n\"The housekeeper found the room empty at six-forty this morning,\" Sergeant Davies reported. \"His lordship retired to the study around eleven last night—his invariable custom. Security shows no doors or windows were breached overnight.\"\n\nHargrove examined the fireplace ashes. Among charred remnants of correspondence, she detected fragments of legal stationery. Someone had been burning contracts.\n\n\"Pull every financial record and every beneficiary going back eighteen months. Find out who inherits if Lord Ashworth is declared deceased.\"\n\nThe peculiar detail that nagged at her was the dog. Lord Ashworth's springer spaniel, fiercely devoted to its master, had been found sleeping contentedly in the kitchen—neither barking nor distressed.\n\nEither the dog had been sedated, or it recognized whoever entered. The implications narrowed the suspect pool considerably.\n\nHargrove noticed a barely perceptible scuff mark near the bookcase. She pressed methodically along the shelves until she heard a faint mechanical click.",
