  "translation": "今日、どの主要都市を歩いても、2世代前には想像もできなかった料理の風景に出会う。ペルー・日本のフュージョンレストランがエチオピアのインジェラハウスの隣で営業し、ベトナムのフォー店がオアハカのモーレ専門店と通りを共有している。この美食の多様性は移民と貿易自由化のより広範なパターンを反映している。\n\n料理のグローバル化は情熱的な議論を生んでいる。支持者は料理の交流が相互理解を促進し、移民の起業家に機会を創出し、狭い食のレパートリーを超えて消費者の味覚を広げると主張する。批判者は伝統的な食文化の商品化が料理から文化的意義を剥ぎ取ると主張する。神聖なレシピが大量生産されると、意味を与えていた共同体的次元が取り返しのつかないほど減じられる。さらに、経済的力学は発祥のコミュニティよりも仲介業者に利益をもたらすことが多い。\n\n特に論争を呼ぶ次元は本物性に関わる。料理人類学者は静的な概念をますます拒否し、すべての料理は接触と即興を通じて進化すると主張する。現代の東京の寿司は江戸時代の前身とほとんど似ていないが、その正当性を疑う人はほとんどいない。\n\nおそらく最も生産的な枠組みは、食が同時に栄養、芸術、商業、文化的表現であることを認め、厳格な規範ではなく継続的な対話が必要であると認識するものだろう。"
