  "difficulty": "TOEFL iBT",
  "wordCount": 152,
  "text": "When someone decides to leave their job, they rarely say \"I am resigning.\" Instead, they might say, \"I'm about to bounce,\" meaning they plan to leave soon. If someone leaves suddenly without much explanation, people say they \"dipped\" — as in, \"She just dipped after the meeting and never came back.\" Another casual way to announce a departure is to \"peace out,\" which is a relaxed, almost humorous goodbye. When someone has simply had enough, they \"call it quits.\" A coworker might say, \"After ten years of dealing with that boss, I finally called it quits.\" You might also hear \"put in my two weeks,\" referring to giving a two-week notice. In more dramatic situations, people talk about \"rage quitting,\" which means leaving in anger without any plan. These expressions capture the emotions behind career changes far better than formal language ever could.",
