  "translation": "誰かが仕事を辞めると決めたとき、「辞任します」とはまず言わない。代わりに「もうすぐbounceするよ」と言うかもしれない。これはもうすぐ去る予定だという意味だ。もし誰かがあまり説明もなく突然いなくなったら、「dipped」と言う。「彼女はミーティングの後にdipして、二度と戻ってこなかった」というように。もうひとつ退職を告げるカジュアルな言い方が「peace out」で、リラックスした、ちょっとユーモラスなさよならだ。もう十分だと思ったときは「call it quits」する。同僚がこう言うかもしれない。「あの上司に10年付き合った末に、ようやくcall it quitsした」。「put in my two weeks（2週間前通知を出す）」という表現も聞くだろう。これは2週間前の退職届を出すことを指す。もっと劇的な状況では「rage quitting（キレて辞める）」について話す。これは計画もなく怒りに任せて辞めることだ。こうした表現は、フォーマルな言葉では到底表現できないほど、キャリアの転機に伴う感情を生き生きと捉えている。"
