  "translation": "現代のアメリカンスラングで何かを褒めたいなら、「good」や「excellent」は忘れよう。今の定番ワードは「fire」だ。「その服fireだね」と言えば、すごく良く見えるという意味だ。食文化からは「bussin」が生まれた。もともとは美味しい食べ物を表す言葉だったが、今では印象的なもの何にでも使う。「このプレイリストはbussinだ」はその選曲が一流だという意味。同様に「slaps」は音楽、食べ物、楽しいもの全般に使う。「この曲マジでslapsする」。おそらく最も詩的な表現は「hits different」で、何かが特別に感じられるという意味だ。「雨の朝のコーヒーはhits differentだ」。これらの用語はブラック・アメリカンの日常語やネット文化から主流の会話に広がった。上の世代には紛らわしいかもしれないが、若い話者にとっては正確な感情的ニュアンスを持っている。それぞれの言葉は単なる賛意だけでなく、従来の形容詞では時に表現しきれない熱意や心からの興奮を伝えている。"
