  "title": "It's Complicated: Modern Dating Slang Decoded",
  "difficulty": "TOEFL iBT+",
  "wordCount": 155,
  "text": "Modern dating has its own vocabulary that can confuse even native speakers. Before two people are officially a couple, they might be in the \"talking stage,\" a gray area where they text and flirt but have made no commitment. If this unclear arrangement continues for months, it becomes a \"situationship\" — something between friendship and a relationship with no labels. At some point, one person might want to \"DTR,\" which stands for \"define the relationship.\" This conversation can be terrifying because the other person might not feel the same way. When someone starts developing romantic emotions unexpectedly, they are \"catching feelings.\" A friend might warn, \"Be careful — you're catching feelings for someone who just wants to keep things casual.\" Other terms include \"ghosting,\" where someone disappears without explanation, and \"breadcrumbing,\" where a person sends just enough messages to keep you interested without real intention. These expressions reflect the anxiety of navigating romance in the digital age.",
