  "difficulty": "TOEFL iBT",
  "wordCount": 150,
  "text": "Social media has created an entirely new vocabulary. When a post spreads rapidly across the internet, it \"goes viral.\" A tweet, video, or meme can go viral overnight, reaching millions of people. But fame on social media is a double-edged sword. Getting \"ratio'd\" means your post receives more negative replies than likes, signaling public disapproval. People chase \"clout,\" which refers to influence or popularity online. Someone might post controversial opinions just for clout rather than genuine belief. At the center of this ecosystem are \"influencers,\" people who have built large followings and can shape opinions or promote products. Being an influencer sounds glamorous, but it involves constant content creation and managing public perception. Related terms include \"going live,\" broadcasting in real time, and \"algorithm,\" the invisible system that decides what content people see. Understanding these terms is essential for anyone navigating today's digital landscape.",
