  "translation": "誰でも時には怒るが、英語のスラングはその感情を表す色鮮やかな言い方を提供する。「salty」な人は、些細なことで苦々しく思ったり怒ったりしている。「彼女は先週の試合に負けたことをまだsaltyだ」。「pressed」は、何かに目に見えて気を揉んだり、過度に気にしていることを意味する。「彼が言ったことについてなぜそんなにpressedなの？」怒りが激しくなると、「heated」になる。heatedな議論とは、感情が高ぶり、声を荒らげるようなものだ。「triggered」という言葉はもともと心理学から来ており、トラウマに対する感情的反応を表していたが、カジュアルな会話では今や簡単に動揺したり怒ったりすることを意味する。「ピザにパイナップルのことを誰かが言うと、彼はtriggeredになる」。これらのスラングには強度の違いがある。saltyは軽い苛立ち、pressedは不必要な心配、heatedは本気の怒り、triggeredは過剰反応に対する嘲笑的なニュアンスを含むことが多い。適切な言葉を選ぶことが重要だ。"
