  "difficulty": "TOEFL iBT",
  "wordCount": 149,
  "text": "When something surprises you so much that you cannot process it, English slang has you covered. \"Mind-blown\" describes the feeling when something completely changes your understanding. \"When I learned that octopuses have three hearts, I was mind-blown.\" The phrase \"I can't even\" is deliberately incomplete — the speaker is so overwhelmed they cannot finish their sentence. \"She showed up in a wedding dress to a casual dinner. I can't even.\" Saying \"I'm dead\" means something was so funny or shocking that you figuratively died from the impact. \"Did you see that video? I'm dead.\" Taking it further, \"shooketh\" is a dramatic, humorous version of \"shook,\" meaning deeply shocked or disturbed. \"When the plot twist happened, I was absolutely shooketh.\" These expressions thrive on exaggeration. Nobody is literally dying or unable to speak. The humor comes from treating minor surprises as earth-shattering events, and that playful drama is what makes them so popular.",
