  "title": "GG: The Secret Language of Gamers and Tech Culture",
  "difficulty": "TOEFL iBT",
  "wordCount": 154,
  "text": "Gaming culture has produced slang that has leaked into everyday conversation. \"Lag\" originally meant a delay in a game's response time, but now people use it for any slow situation. \"My brain is lagging today\" means you are thinking slowly. A \"glitch\" is a small error or malfunction, and people say \"I had a glitch\" when they make a silly mistake in real life. \"AFK\" stands for \"away from keyboard\" and gamers use it when stepping away briefly, but office workers now say, \"I'll be AFK for lunch.\" \"Rage quit\" means leaving a game — or any frustrating situation — in anger. \"She rage quit the group project after the third argument.\" When game developers weaken a character or feature, they \"nerf\" it. In real life, \"They nerfed the employee discount\" means benefits were reduced. \"GG,\" short for \"good game,\" is used to acknowledge a well-fought competition or simply to say \"it's over.\" These terms show how gaming vocabulary has become part of mainstream English.",
