  "translation": "ゲーム文化は日常会話に浸透したスラングを生み出した。「lag」はもともとゲームの応答時間の遅延を意味したが、今では遅い状況全般に使われる。「今日は脳がlaggingしている」は考えが鈍いという意味だ。「glitch」は小さなエラーや故障で、現実でうっかりミスをした時に「glitchがあった」と言う。「AFK」は「away from keyboard（キーボードから離れている）」の略で、ゲーマーが一時的に席を外す時に使うが、今やオフィスワーカーも「ランチでAFKします」と言う。「rage quit」はゲーム — あるいはどんなフラストレーションのたまる状況でも — 怒って去ることだ。「3回目の口論の後、彼女はグループプロジェクトをrage quitした」。ゲーム開発者がキャラクターや機能を弱体化させると「nerf」する。現実では「社員割引がnerfされた」は福利厚生が削減されたという意味だ。「GG」は「good game」の略で、よく戦った勝負を称えたり、単に「終わった」と言うのに使う。これらの用語はゲーム語彙がいかに主流の英語の一部となったかを示している。"
