  "translation": "失敗は英語で最も鮮やかなスラングのいくつかを生み出した。「blew it」は機会を台無しにしたり、致命的なミスをしたということだ。「彼女をデートに誘う完璧なチャンスがあったのに、完全にblew itした」。「choked」はプレッシャーの下で失敗したことを意味し、特に成功が期待されていた時に使う。アスリートは最終局面で重要なショットを外すとchokeする。「彼はチャンピオンシップゲームでchokedして、決勝シュートを外した」。「tanked」は何かが完全に、そして派手に失敗したことを表す。「新製品はtankedした — 誰も買わなかった」。おそらく最も視覚的な表現は「face-plant」で、文字通りは顔面から地面に倒れることだが、どんな恥ずかしい失敗にも比喩的に使われる。「私の就職面接は完全なface-plantだった」。これらの言葉にはドラマチックさと身体性があり、普通のミスを映画のような大惨事に変える。興味深いことに、アメリカ人はこれらの用語を恥ではなくユーモアで使うことが多く、対処して前に進む方法として自分の失敗を笑い飛ばすのだ。"
