  "title": "Score! Slang for Saving Money and Finding Deals",
  "difficulty": "TOEFL iBT",
  "wordCount": 148,
  "text": "Everyone loves saving money, and English has plenty of slang for frugal behavior. A \"thrifty\" person is skilled at spending as little as possible without being cheap. \"My grandmother was thrifty — she could feed a family of six on twenty dollars.\" \"Penny-pinching\" is similar but slightly more negative, suggesting someone is overly careful with money. \"Stop being so penny-pinching and buy yourself something nice.\" When you find an amazing bargain, you \"score a deal.\" \"I scored a deal on flights — round trip for just two hundred dollars!\" A \"freebie\" is anything you receive without paying. \"The company gave out freebies at the trade show.\" Related expressions include \"budget-friendly,\" meaning affordable, and \"bang for your buck,\" meaning great value for the price. \"This phone gives you the best bang for your buck.\" In a culture where both spending and saving are celebrated, these terms help people talk about money without sounding too serious or judgmental.",
