  "title": "Keep It on the DL: Slang for Secrets and Discretion",
  "difficulty": "TOEFL iBT",
  "wordCount": 149,
  "text": "Secrets are a part of life, and English slang has many ways to talk about keeping them. \"DL\" or \"on the down low\" means keeping something secret or private. \"We're dating, but we're keeping it on the DL for now.\" \"Hush-hush\" is a slightly older expression meaning something is confidential and should not be discussed openly. \"The merger is still hush-hush — don't tell anyone.\" To \"keep it under wraps\" means to hide information until the right time. \"The company kept the new product under wraps until the launch event.\" Other related terms include \"off the record,\" meaning information shared privately that should not be made public, and \"between you and me,\" a signal that what follows is confidential. \"Between you and me, the boss is planning to resign.\" These phrases are essential in professional and social settings where discretion matters. They create trust between speakers by establishing clear boundaries around sensitive information and showing respect for privacy.",
