  "title": "Drowning in Work: Slang for Being Extremely Busy",
  "difficulty": "TOEFL iBT",
  "wordCount": 152,
  "text": "When work piles up, English speakers reach for dramatic language. \"Swamped\" means overwhelmed with too much work. \"I can't meet for lunch — I'm completely swamped this week.\" Similarly, \"slammed\" describes being hit with an intense volume of tasks, as if physically struck. \"The restaurant was slammed on Saturday night — every table was full.\" \"Drowning\" takes the metaphor further, suggesting you are so buried in work that you can barely survive. \"I'm drowning in emails and can't keep up.\" The most vivid expression might be \"burning the candle at both ends,\" an old idiom meaning you are working so hard, from early morning to late at night, that you are exhausting yourself. \"She's been burning the candle at both ends preparing for the product launch.\" Other useful terms include \"spread thin,\" meaning handling too many responsibilities, and \"running on fumes,\" operating with almost no energy left. These expressions help communicate not just busyness but the emotional and physical toll it takes.",
