  "translation": "仕事が積み重なると、英語話者は劇的な言い回しに手を伸ばす。「swamped」は仕事が多すぎて圧倒されていることだ。「ランチに会えない — 今週は完全にswampedだ」。同様に「slammed」は、まるで物理的に打たれたかのように、大量のタスクに見舞われていることを表す。「土曜の夜、レストランはslammedだった — 全テーブルが満席だった」。「drowning」はメタファーをさらに進め、仕事に埋もれてかろうじて生き残っている状態を示す。「メールにdrowningしていて追いつけない」。最も鮮やかな表現は「burning the candle at both ends」かもしれない。早朝から深夜まで懸命に働きすぎて自分を消耗しているという古いイディオムだ。「彼女は製品発売の準備でburning the candle at both endsしている」。他に便利な用語には「spread thin」、多すぎる責任を抱えていること、「running on fumes」、ほとんどエネルギーが残っていない状態で動いていることがある。これらの表現は単に忙しいだけでなく、それが及ぼす感情的・身体的な代償を伝える助けになる。"
