  "difficulty": "TOEFL iBT+",
  "wordCount": 152,
  "text": "When our startup lost its primary investor, we had to make do with what we had. The CEO made a point of addressing the team honestly, explaining that salaries would be frozen for six months. At first, it didn't make sense to keep hiring, so we paused recruitment entirely. Some employees quit, but those who stayed made up for the smaller workforce by taking on extra responsibilities. We made progress slowly, and every small win made a difference to morale. Looking back, the crisis made way for a leaner, more resilient company culture. The experience taught us that constraints can actually make room for creativity. By the end of the year, we had not only survived but made headway into two new markets. Sometimes you have to make the best of a bad situation to discover what your team is truly capable of.",
