  "text": "The factory had been losing money for three consecutive years. Many analysts expected it to shut down, but the new director was determined to turn things around. Her first move was controversial—she turned down a lucrative outsourcing deal because it would have meant laying off half the workforce. Critics said her idealism would turn out to be the company's downfall. She didn't turn a blind eye to the financial reality, though. Instead, she turned her attention to operational efficiency. Old machines were replaced, and workers were retrained. It turned out that the biggest waste came from outdated processes, not from labor costs. Within eighteen months, the factory had turned a profit for the first time in years. Employees who had once turned against management began to rally behind her leadership. Sometimes, the courage to turn down easy money is exactly what it takes to turn a failing business into a thriving one.",
