  "difficulty": "TOEFL iBT+",
  "wordCount": 151,
  "text": "Even the most carefully crafted plans can fall through without warning. Our company's acquisition deal, which had been months in the making, fell apart at the last minute when the target company's board raised unexpected demands. We had fallen behind on our growth targets, and losing this deal made things worse. Morale fell sharply, and some team members fell into a pattern of blaming each other for the failure. But our CEO refused to let the team fall prey to negativity. She reminded everyone that falling short of a goal is not the same as failing entirely. Gradually, things began to fall into place as we shifted our focus to organic growth. A smaller partnership opportunity fell into our lap unexpectedly. It fell short of the original acquisition in scale, but it was exactly what we needed to rebuild momentum. Sometimes the plans that fall through make way for outcomes that far exceed your expectations.",
