  "difficulty": "TOEFL iBT+",
  "wordCount": 150,
  "text": "Our team recently had to work through a major operational crisis after a system upgrade went sideways. The new software didn't work out as expected, and we spent three days trying to work around the bugs. Our engineers worked tirelessly, and their dedication worked wonders—they restored full functionality by Friday morning. The experience taught us to work up to major changes gradually rather than deploying everything at once. Some team members worked up the courage to tell management that the rollout timeline had been unrealistic from the start. Rather than punishing honesty, the CTO worked with the team to create a more realistic deployment schedule. This collaborative approach worked out well for everyone. Interestingly, the crisis also worked in our favor by exposing weaknesses we hadn't known about. If you work at something long enough and refuse to give up, solutions tend to work themselves out naturally.",
