  "text": "The distinction between \"lay\" and \"lie\" confuses even advanced English learners, but mastering their collocations is essential. Our CEO spent her first year laying the groundwork for a complete organizational restructuring. She knew that challenges lay ahead, but she also understood that success lies in preparation. Before announcing the changes, she laid out a detailed timeline for every department. Some employees were laid off during the transition—a painful but necessary step. Rather than letting rumors spread, she laid bare the financial realities that made the restructuring unavoidable. She advised the remaining staff to lie low during the transition period and focus on their core responsibilities. The foundation she laid proved solid. Two years later, the company was thriving, and the groundwork she had laid was paying dividends. The responsibility for what lies ahead now rests with the next generation of leaders. As the saying goes, you reap what you sow—or more precisely, you harvest what you carefully lay down.",
