  "difficulty": "TOEFL iBT+",
  "wordCount": 156,
  "text": "Unlike earlier chatbots that merely answered questions, AI agents can autonomously plan and execute multi-step tasks: booking travel, reconciling invoices, or drafting legal documents with minimal supervision. Their proliferation across corporate workflows is quietly redrawing the boundary between human and machine labor.\n\nThe economic implications are ambiguous. Optimists argue that agents will absorb tedious cognitive chores, liberating workers for judgment-intensive roles and lifting stagnant productivity. Skeptics counter that the displacement will fall disproportionately on entry-level white-collar positions, eroding the traditional rungs by which young professionals acquire tacit skills.\n\nHistory offers a cautionary nuance. Technological revolutions have ultimately created more jobs than they destroyed, but the transition periods were often wrenching, lasting decades and hollowing out entire occupations.\n\nThe prudent response is neither complacency nor prohibition, but deliberate adaptation: redesigning career ladders, subsidizing retraining, and ensuring that the surplus generated by automation is broadly shared rather than narrowly captured.",
