  "text": "GLP-1 receptor agonists, originally developed for diabetes, have proven remarkably efficacious at inducing weight loss, and their adoption has surged across developed economies. The pharmacological breakthrough now poses an unprecedented actuarial question: can health systems afford a therapy that tens of millions of patients may take indefinitely?\n\nThe upfront costs are staggering. At list prices exceeding several hundred dollars per month, universal coverage for eligible populations would consume a substantial share of national pharmaceutical budgets. Insurers consequently ration access through prior authorization and step therapy requirements.\n\nProponents emphasize offsetting savings: obesity is a principal driver of cardiovascular disease, joint replacements, and lost productivity, so effective treatment should curtail downstream expenditures. Yet the fiscal payoff accrues over decades, while the drug bill arrives immediately—a temporal mismatch that strains annual budgeting cycles.\n\nThe resolution will likely combine price negotiation, generic competition upon patent expiry, and outcome-based contracts that tie reimbursement to demonstrated health improvements.",
