  "difficulty": "Academic",
  "wordCount": 157,
  "text": "For a decade after the global financial crisis, advanced economies borrowed at negligible cost, and prominent economists argued that elevated public debt was benign so long as interest rates remained below growth rates. That comfortable arithmetic has inverted. With policy rates normalized and term premiums rebuilding, debt service is absorbing a swelling share of government revenue.\n\nThe mechanics are unforgiving. As maturing bonds are refinanced at higher coupons, the average interest burden ratchets upward even without new deficits. Countries with short average maturities or heavy reliance on foreign creditors face the swiftest repricing.\n\nMarkets discipline the profligate unevenly. Reserve-currency issuers enjoy considerable latitude, whereas smaller sovereigns confront abrupt spikes in risk premia when credibility falters.\n\nRestoring sustainability requires some combination of primary surpluses, structural growth reforms, and occasionally financial repression—channeling captive domestic savings into government paper at suppressed yields. Each path imposes distributional costs that electorates, already weary of austerity, may prove unwilling to bear.",
