  "translation": "世界金融危機後の10年間、先進国は無視できるほどのコストで借り入れを行い、著名な経済学者たちは、金利が成長率を下回る限り高水準の公的債務は無害だと主張した。その快適な算術は逆転した。政策金利が正常化しタームプレミアムが再構築される中、債務の元利払いは政府歳入の膨れ上がる割合を吸収しつつある。\n\nそのメカニズムは容赦がない。満期を迎える国債がより高いクーポンで借り換えられるにつれ、新たな財政赤字がなくても平均利払い負担は段階的に上昇する。平均満期が短い国や外国債権者への依存度が高い国は、最も速い価格再評価に直面する。\n\n市場は浪費的な国を不均等に律する。基軸通貨の発行国はかなりの裁量の余地を享受する一方、より小さな国は信頼が揺らぐとリスクプレミアムの急騰に直面する。\n\n持続可能性の回復には、プライマリーバランス黒字、構造的な成長改革、そして時には金融抑圧――囚われた国内貯蓄を抑制された利回りで国債に誘導すること――の組み合わせが必要となる。いずれの道も分配上のコストを課すものであり、すでに緊縮に疲れた有権者はそれを負担する意思を示さないかもしれない。"
