  "wordCount": 155,
  "text": "Since banks retrenched under post-crisis capital rules, private credit funds have filled the vacuum, extending loans directly to mid-sized companies. The asset class has ballooned into a multi-trillion-dollar market, prized by institutional investors for its floating-rate yields and apparent insulation from daily market volatility.\n\nThat insulation, however, is partly an artifact of infrequent valuation. Because loans are marked quarterly by managers rather than priced continuously by markets, reported returns appear deceptively smooth—a phenomenon critics label volatility laundering.\n\nStructural vulnerabilities are accumulating beneath the placid surface. Covenant protections have loosened amid competition for deals; borrowers increasingly defer cash interest through payment-in-kind provisions; and leverage is layered at both the fund and portfolio-company level.\n\nNone of this guarantees a crisis. But opacity means distress may remain concealed until refinancing walls arrive. Regulators, mindful that risk has migrated rather than vanished, are belatedly demanding greater transparency from a sector built on discretion.",
