  "translation": "危機後の自己資本規制の下で銀行が融資を縮小して以来、プライベートクレジットファンドがその空白を埋め、中堅企業に直接融資を行ってきた。この資産クラスは数兆ドル規模の市場へと急膨張し、変動金利の利回りと日々の市場変動から見かけ上遮断されている点で機関投資家に珍重されている。\n\nしかしその遮断は、部分的には評価頻度の低さがもたらす人為的産物である。ローンは市場で継続的に価格付けされるのではなく、運用者によって四半期ごとに評価されるため、報告されるリターンは欺くほど滑らかに見える。批判者はこの現象をボラティリティ・ロンダリングと呼ぶ。\n\n穏やかな表面の下で、構造的な脆弱性が蓄積している。案件獲得競争の中でコベナンツによる保護は緩み、借り手は現物払い（PIK）条項を通じて現金利払いをますます繰り延べ、レバレッジはファンドと投資先企業の両方のレベルで積み重なっている。\n\nこれらのいずれも危機を保証するものではない。しかし不透明性ゆえに、経営難は借り換えの壁が到来するまで隠れたままかもしれない。リスクは消えたのではなく移動しただけだと認識する規制当局は、遅ればせながら、裁量の上に築かれたこのセクターにより高い透明性を求め始めている。"
