  "difficulty": "TOEFL iBT+",
  "wordCount": 154,
  "text": "The clean-energy transition has transformed obscure elements—lithium, cobalt, rare earths, gallium—into strategic commodities. Electric vehicles, wind turbines, and advanced semiconductors all hinge on these inputs, and their supply chains are strikingly concentrated: a handful of countries dominate extraction, while one dominates refining.\n\nThis concentration confers leverage. Export restrictions on critical minerals have already been deployed as instruments of statecraft, prompting importing nations to scramble for alternatives. The resulting policies blend industrial subsidy with diplomacy: friend-shoring agreements, strategic stockpiles, and lavish incentives for domestic processing plants.\n\nYet diversification is easier proclaimed than accomplished. New mines take a decade or more to permit and construct, refining is capital-intensive and environmentally contentious, and recycling volumes remain modest.\n\nThe unavoidable conclusion is that mineral security now sits alongside energy security in national strategy. Countries that ignore the vulnerability do so at their peril, for the age of geologically indifferent globalization has ended.",
