  "wordCount": 156,
  "text": "Across East Asia and much of Europe, fertility rates have sunk far below replacement level, and populations are aging with unprecedented speed. The arithmetic of pay-as-you-go pension systems, in which current workers finance current retirees, deteriorates mechanically as the ratio of contributors to beneficiaries erodes.\n\nGovernments possess a limited menu of remedies: raising retirement ages, increasing contribution rates, trimming benefits, admitting more immigrants, or prefunding obligations through sovereign investment vehicles. Each option is actuarially straightforward and politically treacherous. Pension reform has toppled governments, and gray electorates—whose voting turnout dwarfs that of the young—wield formidable veto power.\n\nDelay, however, merely compounds the burden. Actuaries warn that every postponed adjustment shifts costs onto a shrinking cohort of future workers, straining intergenerational equity.\n\nThe countries navigating the transition most successfully combine gradualism with automatic stabilizers: indexing retirement ages to longevity and adjusting benefits by formula, thereby insulating painful decisions from electoral cycles.",
