  "translation": "東アジアとヨーロッパの多くで、出生率は人口置換水準をはるかに下回り、人口は前例のない速さで高齢化している。現役労働者が現在の退職者を支える賦課方式年金の算術は、拠出者と受給者の比率が悪化するにつれて機械的に劣化していく。\n\n政府が持つ処方箋は限られている。退職年齢の引き上げ、保険料率の引き上げ、給付の削減、移民の受け入れ拡大、あるいは政府系投資機関を通じた債務の事前積立である。いずれの選択肢も保険数理的には単純明快だが、政治的には油断ならない。年金改革は政権を倒してきたし、若者を圧倒する投票率を誇る高齢の有権者層は手ごわい拒否権を握っている。\n\nしかし先送りは負担を悪化させるだけである。保険数理人たちは、調整を先送りするたびに、縮小していく将来世代の労働者にコストが転嫁され、世代間公平が損なわれると警告する。\n\nこの移行を最もうまく乗り切っている国々は、漸進主義と自動安定化装置を組み合わせている。退職年齢を平均寿命に連動させ、給付を計算式で調整することで、痛みを伴う決定を選挙サイクルから遮断しているのだ。"
