    "japanese": "軽く連絡を取り合う・近況確認する",
    "definition": "To make brief contact with someone to share updates.",
    "example": "Let's touch base on Friday before the client meeting.",
    "exampleJa": "クライアントとの会議の前に、金曜に軽くすり合わせしましょう。"
